const P = [
  { id: '691331356a3b9a68428ab3.43540470', name: 'Chat AI - frontend' },
  { id: '225008626a33e62b328c63.04676982', name: 'Chat AI (emails)' }
];
const out = [];
for (const p of P) {
  for (let page = 1; page <= 3; page++) {
    out.push({ json: { kind: 'keys', project_id: p.id, project_name: p.name, page: page, url: 'https://api.lokalise.com/api2/projects/' + p.id + '/keys?limit=500&page=' + page + '&include_translations=1' } });
  }
  for (let page = 1; page <= 3; page++) {
    out.push({ json: { kind: 'screenshots', project_id: p.id, project_name: p.name, page: page, url: 'https://api.lokalise.com/api2/projects/' + p.id + '/screenshots?limit=500&page=' + page } });
  }
}
return out;

const reqs = $('Build Requests').all();
const res = $input.all();
const byProject = {};
function bucket(name) {
  if (!byProject[name]) {
    byProject[name] = { project_name: name, project_id: '', keys: {}, screenshots: [], linked: {}, errors: [] };
  }
  return byProject[name];
}
function sourceText(k) {
  for (const t of (k.translations || [])) {
    const iso = String(t.language_iso || '').toLowerCase();
    if (iso === 'en' || iso.indexOf('en_') === 0 || iso.indexOf('en-') === 0) {
      const v = t.translation;
      if (typeof v === 'string') { return v; }
      if (v && typeof v === 'object') {
        const parts = [];
        for (const kk of Object.keys(v)) { if (v[kk]) { parts.push(String(v[kk])); } }
        return parts.join(' | ');
      }
    }
  }
  return '';
}
function keyName(n) {
  if (typeof n === 'string') { return n; }
  if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android || ''; }
  return '';
}
for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  const b = bucket(meta.project_name);
  b.project_id = meta.project_id;
  const r = res[i].json || {};
  const body = r.body || {};
  if (r.statusCode !== 200) { b.errors.push(meta.kind + ' p' + meta.page + ' -> ' + r.statusCode); continue; }
  if (meta.kind === 'keys') {
    for (const k of (body.keys || [])) {
      b.keys[String(k.key_id)] = {
        key_id: String(k.key_id),
        name: keyName(k.key_name),
        en: sourceText(k),
        tags: k.tags || [],
        description: k.description || '',
        archived: !!k.is_archived,
        platforms: k.platforms || []
      };
    }
  } else {
    for (const s of (body.screenshots || [])) {
      b.screenshots.push({ screenshot_id: s.screenshot_id, title: s.title || '', tags: s.tags || [], key_count: (s.key_ids || []).length });
      for (const kid of (s.key_ids || [])) { b.linked[String(kid)] = true; }
    }
  }
}
const out = [];
for (const name of Object.keys(byProject)) {
  const b = byProject[name];
  const allKeys = Object.keys(b.keys);
  const missing = [];
  let active = 0;
  let covered = 0;
  for (const id of allKeys) {
    const k = b.keys[id];
    if (k.archived) { continue; }
    active++;
    if (b.linked[id]) { covered++; } else { missing.push({ key_id: id, name: k.name, en: k.en, tags: k.tags, description: k.description, platforms: k.platforms }); }
  }
  out.push({ json: {
    project_name: name,
    project_id: b.project_id,
    keys_total: allKeys.length,
    keys_active: active,
    keys_with_screenshot: covered,
    keys_missing_screenshot: missing.length,
    screenshots_existing: b.screenshots.length,
    screenshots: b.screenshots,
    errors: b.errors,
    missing: missing
  } });
}
return out;
